// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;

    function setUp() public {
        c = new PredictTheBlockHashChallenge{value: 1 ether}();
    }

    function testFuzz_property(address player, bytes32 guess, uint256 lockBlockOffset, uint256 settleBlockOffset) public {
        // Keep player from being the test contract or zero.
        vm.assume(player != address(0));
        vm.assume(player != address(this));
        vm.assume(uint160(player) > 1000);

        // Admissible wide domain: player locks at an arbitrary future-ish block, settles at a later block.
        lockBlockOffset = bound(lockBlockOffset, 1, 1000);
        settleBlockOffset = bound(settleBlockOffset, 2, 1000);

        uint256 currentBlock = block.number;
        uint256 lockAt = currentBlock + lockBlockOffset;
        uint256 settleAt = lockAt + settleBlockOffset;

        // Fund the player and lock in a guess.
        vm.deal(player, 2 ether);
        vm.roll(lockAt);
        vm.prank(player);
        c.lockInGuess{value: 1 ether}(guess);

        // Move to a block where settle() is callable (block.number > guesses[player].block).
        // For very recent blocks blockhash may be zero; that is the adversarial/valid case for the reference.
        vm.roll(settleAt);

        // settle() may succeed or revert depending on blockhash availability; only require that it was attempted.
        vm.prank(player);
        try c.settle() {} catch {}

        // General rule: after a settle attempt, the player must be able to lock in a new guess.
        // The reference always clears the guess block (even when answer == 0), so re-locking succeeds.
        // The mutant may revert on answer == 0 and leave the old guess, so re-locking reverts.
        vm.deal(player, 1 ether);
        vm.prank(player);
        bool canRelock;
        try c.lockInGuess{value: 1 ether}(guess) { canRelock = true; } catch { canRelock = false; }

        assertTrue(canRelock);
    }
}
